mapper.sql:
SELECT * FROM ( SELECT a.shop_no AS shopNo, SUBSTR(a.bill_date, 1, 10) AS billDate, sum(a.check_amount) AS checkAmount, sum(if(b.settle_type = 'PAYEE', a.payment_amount, 0)) AS paymentAmount, sum(if(b.settle_type = 'PAYEE', 0, a.payment_amount)) AS deductAmount, sum(a.discount_amount) AS discountAmount, group_concat(a.bill_no) AS billNo, count(a.bill_no) AS billCount FROM rp_order a left join rp_order_settle b on a.bill_no = b.bill_no WHERE a.audit_status = 'YES' and a.bill_date >= #{param.start} and a.bill_date <= #{param.end} and a.bill_type = #{param.billType} and a.shop_no in #{item}
GROUP BY SUBSTR(a.bill_date, 1, 10), a.shop_no ) aa LEFT JOIN ( SELECT c.shop_no, SUBSTR(c.trade_time, 1, 10) AS tradeTime, sum(c.pay_amount) AS payAmount FROM cashier_record c
and c.trade_time >= #{param.start} and c.trade_time <= #{param.end} and c.pay_direct = #{param.payDirect} and c.cost_type in #{item}
and c.shop_no in #{item}
GROUP BY SUBSTR(c.trade_time, 1, 10), c.shop_no ) bb ON aa.billDate = bb.tradeTime and aa.shopNo = bb.shop_no UNION
SELECT * FROM ( SELECT a.shop_no, SUBSTR(a.bill_date, 1, 10) AS billDate, sum(a.check_amount) AS checkAmount, sum(if(b.settle_type = 'PAYEE', a.payment_amount, 0)) AS paymentAmount, sum(if(b.settle_type = 'PAYEE', 0, a.payment_amount)) AS deductAmount, sum(a.discount_amount) AS discountAmount, GROUP_CONCAT(a.bill_no) AS billNo, count(a.bill_no) AS billCount FROM rp_order a left join rp_order_settle b on a.bill_no = b.bill_no WHERE a.audit_status = 'YES' and a.bill_date >= #{param.start} and a.bill_date <= #{param.end} and a.bill_type = #{param.billType} and a.shop_no in #{item}
GROUP BY SUBSTR(a.bill_date, 1, 10), a.shop_no ) aa RIGHT JOIN ( SELECT c.shop_no AS shopNo, SUBSTR(c.trade_time, 1, 10) AS tradeTime, sum(c.pay_amount) AS payAmount FROM cashier_record c
and c.trade_time >= #{param.start} and c.trade_time <= #{param.end} and c.pay_direct = #{param.payDirect} and c.cost_type in #{item}
and c.shop_no in #{item}
GROUP BY SUBSTR(c.trade_time, 1, 10), c.shop_no ) cc ON aa.billDate = cc.tradeTime and aa.shop_no = cc.shopNo

